fn main() {
 let content=mmorpg_core::greyhaven_vale::content(); let def=content.definition();
 let fixed=def.colliders().iter().map(|c|serde_json::json!([c.id,c.position,c.half_extents])).collect::<Vec<_>>();
 let grid=def.spawn_grid();
 let spawns=(0..128).map(|slot|{let mut p=grid.feet(slot).unwrap();p[1]=90;p}).collect::<Vec<_>>();
 let npcs=content.npcs().iter().map(|n|serde_json::json!([n.id.get(),n.position])).collect::<Vec<_>>();
 println!("{}",serde_json::json!({"source_repository":"moritzbrantner/mmorpg","source_revision":"20d34fbb2d9d7014e4bfb089ed1fb85fd1e9eddc","content_revision":def.revision(),"gravity":def.gravity(),"fixed":fixed,"spawns":spawns,"npcs":npcs}));
}
